二叉排序树的链表节点定义如下：<br> <pre class="prettyprint">typedef struct BiTnode{
    int key_value;
    struct BiTnode *L,*R;/*节点的左、右树指针*/
}</pre> <br> 请补充完整查找键值key的函数。<br> <pre class="prettyprint">BSTree lookup_key(BSTree root,int key)
{
    if() return NULL;
    else 
        if(key == root-&gt;key_value)
            return root;
        else if(key &gt; root-&gt;key_value)
            return (1);
        else
            return (2);
}</pre> <br>

设t是给定的一棵二叉树，下面的递归程序count(t)用于求得： <pre class="prettyprint">typedef struct node
{
    int data;
    struct node *lchild,*rchild;
}node;

int N2 = 0,NL = 0,NR = 0,N0 = 0;
void count(node *t)
 {
     if (t-&gt;lchild!=NULL)
         if (t-&gt;rchild!=NULL) N2++;
         else NL++;
     else if (t-&gt;rchild!=NULL) NR++;
     else N0++;
     if(t-&gt;lchild!=NULL) count(t-&gt;lchild);
     if(t-&gt;rchild!=NULL) count(t-&gt;rchild);
 }/* call form :if(t!=NULL) count(t);*/
</pre> <br>
